`,pdfUrl="/portfolio/assets/kidneyPaper-RRW2WjII.pdf";function KidneyPage(){return jsxRuntimeExports.jsxs("div",{style:{display:"flex",flexDirection:"column",height:"100%"},children:[jsxRuntimeExports.jsx(GlassGlobalStyle,{$compactNav:!0,$flushNav:!0}),jsxRuntimeExports.jsxs(Nav,{children:[jsxRuntimeExports.jsx(NavLogoSection,{children:jsxRuntimeExports.jsxs(LogoBox,{children:[jsxRuntimeExports.jsxs("a",{href:"/portfolio/",children:[jsxRuntimeExports.jsx(Logo,{src:logoImg,alt:"Logo"})," "]}),jsxRuntimeExports.jsx(NBTitle,{children:"Nick Brady"})]})}),jsxRuntimeExports.jsx(WideNavLinkSection$4,{children:jsxRuntimeExports.jsxs(LinkBox,{children:[jsxRuntimeExports.jsx("a",{href:"https://www.linkedin.com/in/nickmbrady",target:"_blank",rel:"noopener noreferrer",children:jsxRuntimeExports.jsx(FontAwesomeIcon,{icon:faLinkedin,size:"1x"})}),jsxRuntimeExports.jsx("a",{href:"mailto:nickbrady8444@example.com",children:jsxRuntimeExports.jsx(FontAwesomeIcon,{icon:faEnvelope,size:"1x"})}),jsxRuntimeExports.jsx("a",{href:"https://github.com/nickmbrady",target:"_blank",rel:"noopener noreferrer",children:jsxRuntimeExports.jsx(FontAwesomeIcon,{icon:faGithub,size:"1x"})})]})})]}),jsxRuntimeExports.jsx(Main,{children:jsxRuntimeExports.jsxs(ContentContainer,{children:[jsxRuntimeExports.jsx(BoldTitle,{children:"Autonomous Kidney Stone Detection and Guidance"}),jsxRuntimeExports.jsxs(BubbleDiv,{children:[jsxRuntimeExports.jsx(KeywordBubble,{children:"Computer Vision"}),jsxRuntimeExports.jsx(KeywordBubble,{children:"Software Development"}),jsxRuntimeExports.jsx(KeywordBubble,{children:"3D Slicer"}),jsxRuntimeExports.jsx(KeywordBubble,{children:"Robotics"})]}),jsxRuntimeExports.jsx(Paragraph,{children:"I created an open-source 3D Slicer extension for the detection of and two-stage navigation toward kidney stones using a robotic ureteroscope. During gross guidance, preliminary targets are identified with hue, stabilized through temporal averaging, and validated with K-means grouping. Then, during fine guidance, a hue-and-lightness based region growing algorithm accurately segments stones in preparation for laser lithotripsy (ablation). Software devlopment was done using the 3D Slicer Python API, and OpenCV was used for computer vision."}),jsxRuntimeExports.jsx(Paragraph,{children:"I completed this work during a 10-week internship at the Harvard SNR Lab under the guidance of Professor Nobuhiko Hata."}),jsxRuntimeExports.jsx(SubHeading,{children:"Demo Video"}),jsxRuntimeExports.jsx(YouTubeContainer,{children:jsxRuntimeExports.jsx("iframe",{src:"https://www.youtube.com/embed/_72YArMZDpo?mute=1",title:"Autonomous Kidney Stone Detection and Guidance",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowFullScreen:!0})}),jsxRuntimeExports.jsxs(SubHeading,{children:[jsxRuntimeExports.jsx("br",{})," ",jsxRuntimeExports.jsx("br",{}),"Paper"]}),jsxRuntimeExports.jsx(PdfContainer,{children:jsxRuntimeExports.jsx(PdfViewer,{fileUrl:pdfUrl})})]})})]})}const WideNavLinkSection$4=dt(NavLinkSection)`
